<!-- THROWAWAY v2: /nas?variant=A|B|C compares disk-first, wizard and app-first entry. Memory-only fixtures. -->
<template>
  <main class="lh-prototype" data-lighthost-prototype>
    <div class="lh-demo"><span>存储交互稿 · 示例数据 · 所有操作仅为演示</span><label>场景<select aria-label="预览场景" :value="scene" @change="changeScene"><option value="new">新存储空间</option><option value="ordinary">已有普通文件</option><option value="managed">已准备主机与应用存储</option><option value="mixed">普通文件＋主机＋应用</option><option value="foreign">未知来源的 LVM</option><option value="unsupported">缺少存储组件</option><option value="no-management">没有管理文件位置</option><option value="failure">准备过程失败</option></select></label><button @click="reset">重新演示</button><ThemeSelector /></div>
    <div class="lh-crumb"><router-link to="/">首页</router-link><span>›</span>存储管理</div>
    <header class="lh-heading"><div><p class="lh-eyebrow">STORAGE</p><h1>{{variant==='B'?'为这块空间安排用途':variant==='C'?'从应用开始安排存储':'存储管理'}}</h1><p>继续使用普通文件存储，或按需要安排主机和应用空间。</p></div><span class="lh-badge">{{plan?'存储已准备':'选择空间后开始设置'}}</span></header>
    <nav class="sp-tabs" aria-label="存储页面"><button :class="{active:tab==='storage'}" :disabled="busy" @click="tab='storage'">磁盘与存储</button><button :class="{active:tab==='volumes'}" :disabled="busy" @click="tab='volumes';opened=false">应用卷 <small>{{volumes.length}}</small></button></nav>
    <template v-if="tab==='volumes'">
      <header class="lh-section-title"><div><h2>应用卷</h2><p class="lh-footnote">为一种用途创建一份独立存储；创建后，再交给对应应用使用。</p></div><button v-if="plan?.apps" class="primary" @click="openVolume">创建应用卷</button></header>
      <div v-if="!plan?.apps" class="sp-empty"><span>▦</span><h2>先准备应用存储</h2><p>{{plan?.hosts?'这块空间目前用于 LightHost 主机，需要另一块可用空间准备应用存储。':'选择一块硬盘、分区或未分配空间，用于应用存储。'}}</p><button class="primary" @click="tab='storage';openSetup('apps')">选择空间</button></div>
      <template v-else>
        <div class="sp-capacity-summary"><span>应用存储 <strong>{{plan.apps}} GiB</strong></span><span>卷容量合计 <strong>{{volumeCapacity}} GiB</strong></span><span>尚可分配 <strong>{{available}} GiB</strong></span><span>实际占用 <strong>{{used.toFixed(1)}} GiB</strong></span></div>
        <p class="lh-footnote">示例采用不超额分配策略。实际占用随写入增长，快照和存储元数据也会占用空间。</p>
        <div v-if="!volumes.length" class="sp-empty"><span>＋</span><h2>还没有应用卷</h2><p>先为 Docker 或 LightHost 管理文件创建一份存储。</p><button class="primary" @click="openVolume">创建第一个应用卷</button></div>
        <div v-else class="sp-volume-list"><article v-for="volume in volumes" :key="volume.id" class="sp-volume"><span class="lh-disk-icon">{{volume.kind==='docker'?'DK':'LH'}}</span><div><h3>{{volume.name}}</h3><p>{{volume.kind==='docker'?'宿主 Docker 数据卷':'LightHost 管理卷'}} · {{volume.capacity}} GiB · 已用 {{volume.used.toFixed(1)}} GiB</p><small>{{volume.kind==='docker'?(volume.connected?'已接入 Docker（演示）':'已创建 · 尚未迁移或接入 Docker'):'已准备 · 等待 LightHost 校验'}}</small></div><button @click="volume.kind==='docker'?openConnection(volume.id):toast('继续 LightHost 校验；管理卷不用于存放主机虚拟磁盘。')">{{volume.kind==='docker'?(volume.connected?'查看接入状态':'接入 Docker'):'继续设置 LightHost'}}</button></article></div>
        <aside class="sp-explainer"><strong>主机的数据盘在哪里创建？</strong><p>给 Linux 主机或虚拟机增加数据盘，请在 LightHost 中操作，使用主机存储。这里的「LightHost 管理卷」保存运行文件和数据库。</p><strong>沙箱卷何时可用？</strong><p>完成启动挂载与重启恢复验证后开放，当前演示中暂不创建。</p></aside>
      </template>
    </template>
    <template v-else>
      <label class="sp-target-picker">选择空间<select aria-label="选择存储空间" :value="target.id" :disabled="busy" @change="changeTarget"><option v-for="item in storageTargets" :key="item.id" :value="item.id">{{item.label}} · {{item.capacity}} GiB</option></select></label>
      <template v-if="variant==='A'||plan">
        <div class="lh-disk-list"><article class="lh-disk muted"><span class="lh-disk-icon">▤</span><div class="lh-disk-info"><h3>iStoreOS 系统分区</h3><p>启动、系统镜像和 overlay · 不提供整盘初始化</p></div><span class="lh-badge">系统保护</span></article><article v-if="!hasExistingFiles||plan" class="lh-disk"><span class="lh-disk-icon">▤</span><div class="lh-disk-info"><h3>{{target.label}} <small>{{target.capacity}} GiB</small></h3><p>{{foreign?'发现已有存储，来源待确认':plan?planSummary:hasExistingFiles?'已有工作文件 · 初始化前需要备份':'可以为主机或应用安排用途'}}</p></div><button class="primary" @click="foreign?foreignOpen=true:plan?showDetails=true:openSetup()">{{foreign?'查看详情':plan?'查看安排':'设置用途'}}</button></article></div>
        <section v-if="hasExistingFiles&&!plan||plan?.files" class="sp-file-panel" data-plain-files>
          <header><span class="lh-disk-icon" aria-hidden="true">▤</span><div><span class="lh-eyebrow">普通文件存储</span><h2>{{target.label}} · EXT4</h2><p>{{plan?.files||target.capacity}} GiB · {{hasExistingFiles&&!plan||plan?.preserveExisting?'已有文件约 24 GiB（示例）':'可用于共享、下载和应用目录'}}</p></div><span class="lh-badge">{{plan?.files?'已挂载':'未挂载'}}</span></header>
          <p v-if="!plan" class="lh-notice">这块空间已有 EXT4 文件系统。可以直接挂载并继续使用，无须改成应用存储。</p><p v-else class="lh-notice">挂载目录：{{plan.fileMount}}。普通文件存储不需要先创建应用卷。</p>
          <p v-if="plan?.managementInFiles" class="lh-footnote">此文件区还保存 LightHost 管理文件，重新格式化前必须先处理应用依赖。</p>
          <div class="sp-file-actions"><button class="primary" @click="plan?.files?openFiles():openSetup('files')">{{plan?.files?'打开文件（演示）':'挂载并使用'}}</button><button v-if="plan?.files" @click="toast('演示：进入原有共享设置，选择当前 EXT4 文件目录。')">文件共享设置</button><button v-if="plan?.files" @click="toast('演示：进入原有 Docker 设置，选择普通 EXT4 数据目录；不提供 LVM 快照。')">用于 Docker 数据目录</button></div>
          <p class="lh-footnote">普通 EXT4 本身不提供 LVM 快照；仍可通过文件备份保存数据。</p>
          <button v-if="!plan" class="sp-text-button" @click="openSetup('both')">重新规划这块空间（会清空原文件）</button>
        </section>
        <div v-if="plan" class="sp-pool-grid"><article v-if="plan.hosts"><span class="lh-eyebrow">LIGHTHOST</span><h2>主机存储</h2><strong>{{plan.hosts}} <small>GiB</small></strong><p>Linux 主机、虚拟机的磁盘与恢复点</p><button @click="toast('进入 LightHost 校验，再创建主机或数据盘。')">继续设置 LightHost</button></article><article v-if="plan.apps"><span class="lh-eyebrow">APPLICATIONS</span><h2>应用存储</h2><strong>{{plan.apps}} <small>GiB</small></strong><p>Docker 数据卷、LightHost 管理卷等</p><button class="primary" @click="tab='volumes'">管理应用卷</button></article></div>
        <p class="lh-footnote">{{target.preserved}}。普通文件共享继续使用现有文件存储入口。</p>
      </template>
      <div v-else-if="variant==='B'" class="lh-purpose-layout"><aside class="lh-step-nav"><span class="lh-eyebrow">空间设置</span><h3>{{target.label}}</h3><p>{{target.capacity}} GiB · {{target.kind==='free'?'只使用未分配范围':'核对清空范围后才执行'}}</p><div>1　选择方式</div><div>2　安排空间</div><div>3　确认范围</div><div>4　准备存储</div><p>完成后可继续创建应用卷。</p></aside><section class="lh-inline-panel"><StorageSetupPrototype v-if="!foreign" :key="setupKey" :target="target" :scene="scene" :initial-purpose="initialPurpose" @complete="complete" @busy="busy=$event" @close="backToOverview" @files="openFiles" @volumes="showVolumes" @continue="toast('进入 LightHost 存储校验。')" /><p v-else class="lh-notice">已有存储，先确认来源。未知来源的 LVM 不提供初始化。</p></section></div>
      <div v-else class="lh-app-layout"><section class="lh-app-intro"><span class="lh-app-icon">▦</span><h2>选择文件存储或运行应用</h2><p>LightHost 主机和宿主应用可以同时使用这块空间。选择用途后，再安排容量。</p><button @click="openSetup('files')">普通文件存储</button><button @click="openSetup('hosts')">运行 LightHost 主机</button><button @click="openSetup('both')">主机和应用都需要</button><button @click="openSetup('apps')">先创建应用卷</button><p class="lh-footnote">虚拟机里的 Docker 随主机磁盘管理；直接运行在 iStoreOS 上的 Docker 使用应用卷。</p></section><section class="lh-app-preview"><StorageSetupPrototype v-if="opened" :key="setupKey" :target="target" :scene="scene" :initial-purpose="initialPurpose" @complete="complete" @busy="busy=$event" @close="close" @files="openFiles" @volumes="showVolumes" @continue="toast('进入 LightHost 存储校验。')" /><template v-else><span class="lh-eyebrow">按用途安排空间</span><h2>主机有磁盘，应用有自己的卷</h2><div class="lh-schematic"><div><b>主机存储</b><span>LightHost</span><small>系统盘、数据盘、快照</small></div><div><b>应用存储</b><span>应用卷</span><small>Docker 数据、管理文件等</small></div></div><p class="lh-footnote">存储分开管理，统一展示。初始化前会列出完整范围。</p></template></section></div>
    </template>
    <div v-if="variant==='A'&&opened" class="lh-overlay" @click.self="close"><section class="lh-drawer" role="dialog" aria-modal="true" aria-label="设置存储用途" tabindex="-1" ref="dialog"><header class="lh-drawer-header"><span>{{target.label}}</span><button aria-label="关闭存储设置" :disabled="busy" @click="close">×</button></header><StorageSetupPrototype :key="setupKey" :target="target" :scene="scene" :initial-purpose="initialPurpose" @complete="complete" @busy="busy=$event" @close="close" @files="openFiles" @volumes="showVolumes" @continue="toast('进入 LightHost 存储校验。')" /></section></div>
    <div v-if="volumeOpen" class="lh-overlay sp-modal-overlay" @click.self="volumeOpen=false"><section class="sp-modal" role="dialog" aria-modal="true" aria-labelledby="sp-volume-title" tabindex="-1" ref="dialog"><header class="lh-drawer-header"><span>应用存储 · 尚可分配 {{available}} GiB</span><button aria-label="关闭创建应用卷" @click="volumeOpen=false">×</button></header><h2 id="sp-volume-title">为哪个应用创建存储？</h2><p class="lh-flow-description">卷是分给一种用途的独立空间，可单独管理容量和恢复点。</p><div class="lh-choices"><button class="lh-purpose" :class="{selected:volumeKind==='docker'}" :aria-pressed="volumeKind==='docker'" @click="volumeKind='docker'"><span class="lh-choice-icon" aria-hidden="true">DK</span><strong>Docker 数据卷</strong><small>保存直接运行在 iStoreOS 上的 Docker 数据。</small></button><button class="lh-purpose" :class="{selected:volumeKind==='management'}" :aria-pressed="volumeKind==='management'" @click="volumeKind='management'"><span class="lh-choice-icon" aria-hidden="true">LH</span><strong>LightHost 管理卷</strong><small>保存运行文件和数据库，不存放主机虚拟磁盘。</small></button><button class="lh-purpose" disabled><span class="lh-choice-icon" aria-hidden="true">▣</span><strong>系统沙箱卷 · 待支持</strong><small>保存沙箱可写数据；需要启动和恢复能力配合。</small></button></div><label class="lh-confirm-label">卷名称<input v-model="volumeName" placeholder="留空则按用途命名" aria-label="卷名称" /></label><label class="sp-volume-size">卷容量<input type="number" v-model.number="volumeSize" min="1" :max="available" aria-label="卷容量" />GiB</label><p v-if="!validVolumeSize" class="lh-notice danger">请输入 1 至 {{available}} GiB 的整数容量。</p><p class="lh-footnote">EXT4 格式保存文件，底层支持按需分配。数据迁移、数据库一致性及恢复由对应应用流程协调。</p><footer class="lh-flow-actions"><button @click="volumeOpen=false">取消</button><button class="primary" :disabled="!validVolumeSize" @click="createVolume">创建应用卷（演示）</button></footer></section></div>
    <div v-if="foreignOpen||ordinaryOpen||showDetails" class="lh-overlay sp-modal-overlay" @click.self="closeInfo"><section class="sp-modal" role="dialog" aria-modal="true" aria-label="存储详情" tabindex="-1" ref="dialog"><header class="lh-drawer-header"><span>{{target.label}}</span><button aria-label="关闭详情" @click="closeInfo">×</button></header><template v-if="foreignOpen"><h2>已有存储，先确认来源</h2><p class="lh-notice">发现未知来源的 LVM。不会将其当作空白空间初始化，请先确认其中的数据及管理应用。</p></template><template v-else-if="ordinaryOpen"><h2>普通文件存储</h2><p class="lh-notice">继续使用原有 EXT4 初始化与挂载流程，适合文件共享和下载目录。应用存储不会替换这个入口。</p><button class="primary" @click="toast('演示：交回原有普通文件初始化流程。');ordinaryOpen=false">继续普通文件设置（演示）</button></template><template v-else><h2>这块空间的安排</h2><p class="lh-notice">{{planSummary}}</p><p v-if="plan?.hosts||plan?.apps">主机存储和应用存储分别由其管理者操作；普通文件区仍可直接使用。</p><p v-else>这是普通 EXT4 文件存储，直接挂载和访问，不必创建 LVM 应用卷。</p><details class="sp-technical"><summary>技术信息</summary><p>LightHost 与系统应用各自拥有独立 VG 和 thin-pool。管理卷上的 EXT4 可以建立在系统应用的 thin 逻辑卷上。</p></details></template></section></div>
    <div v-if="connectingVolume" class="lh-overlay sp-modal-overlay" @click.self="closeConnection"><section class="sp-modal" role="dialog" aria-modal="true" aria-labelledby="sp-connect-title" tabindex="-1" ref="dialog"><header class="lh-drawer-header"><span>应用卷 · {{connectingVolume.name}}</span><button aria-label="关闭 Docker 接入" :disabled="connectStep==='running'" @click="closeConnection">×</button></header>
      <template v-if="connectStep==='review'"><h2 id="sp-connect-title">将 Docker 数据迁入这个卷？</h2><p class="lh-flow-description">卷已经创建。现在需要迁移已有数据，Docker 才会使用它。</p><dl class="lh-facts"><dt>目标卷</dt><dd>{{connectingVolume.name}} · {{connectingVolume.capacity}} GiB</dd><dt>当前数据</dt><dd>{{activeDockerVolume?.name||'现有 Docker 数据目录（示例）'}}</dd><dt>迁移内容</dt><dd>本机 Docker 的受管理数据</dd></dl><p class="lh-notice danger">迁移时将短暂停止 Docker，运行中的应用会中断。迁移并校验完成后，再切换存储位置、启动 Docker。</p><p class="lh-footnote">应用挂载的外部目录与网络存储不自动搬迁。正式执行前会核对实际路径、占用与目标容量。</p><label class="lh-check"><input v-model="connectAck" type="checkbox" /><span>我已了解 Docker 应用会短暂中断。</span></label><footer class="lh-flow-actions"><button @click="closeConnection">稍后接入</button><button class="primary" :disabled="!connectAck" @click="connectDocker">开始接入（演示）</button></footer></template>
      <template v-else-if="connectStep==='running'"><h2 id="sp-connect-title">正在接入 Docker</h2><p class="lh-flow-description">接入任务演示 · DK-DEMO-001</p><ol class="lh-progress"><li v-for="(step,index) in connectionSteps" :key="step" :class="{done:connectProgress>index,current:connectProgress===index}"><b>{{connectProgress>index?'✓':connectProgress===index?'◌':'·'}}</b><span>{{step}}</span></li></ol><p class="lh-notice">这是进度演示，不会停止真实 Docker 或迁移文件。</p></template>
      <template v-else><h2 id="sp-connect-title">Docker 已接入（演示）</h2><div class="lh-success-icon">✓</div><p class="lh-notice">Docker 现在使用「{{connectingVolume.name}}」。应用数据和这个卷的管理关系已建立。</p><dl class="lh-facts"><dt>卷容量</dt><dd>{{connectingVolume.capacity}} GiB</dd><dt>当前状态</dt><dd>已接入 · 演示状态</dd></dl><p class="lh-footnote">后续的快照与恢复需要协调 Docker 应用写入，不能仅凭卷快照就承诺数据库一致性。</p><footer class="lh-flow-actions"><button class="primary" @click="closeConnection">返回应用卷</button></footer></template>
    </section></div>
    <PrototypeSwitcher :variants="variants" />
    <details class="lh-review-state"><summary>评审说明与当前状态</summary><p>方案 {{variant}} · {{target.label}} · {{planSummary||'尚未准备'}} · 应用卷 {{volumes.length}} 个</p><p>按「LightHost 数据卷＝管理文件」设计。普通 EXT4 是默认路径，已有 EXT4 可保留文件挂载；重新规划会清空所选范围。主机附加数据盘在 LightHost 内创建。容量、最低要求与实际部署兼容性待验证；Docker 接入仅模拟进度，沙箱卷尚未实现。刷新重置示例。</p><p>这里的 GiB 容量是示例，不是测试机的真实磁盘或已验证的生产布局。</p></details>
    <p v-if="feedback" class="lh-toast" role="status">{{feedback}}</p>
  </main>
</template>
<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import ThemeSelector from '../home/ThemeSelector.vue'
import PrototypeSwitcher from './PrototypeSwitcher.vue'
import StorageSetupPrototype from './StorageSetupPrototype.vue'
import {storageTargets,type ApplicationVolume,type Purpose,type StoragePlan} from './storagePurposePrototype'
const route=useRoute(),router=useRouter(),scene=computed(()=>String(route.query.scene||'new'))
const variant=computed(()=>['A','B','C'].includes(String(route.query.variant))?String(route.query.variant):'A')
const target=computed(()=>storageTargets.find(item=>item.id===route.query.target)||storageTargets[0])
const variants=[{key:'A',name:'磁盘总览（推荐）'},{key:'B',name:'空间设置向导'},{key:'C',name:'从应用开始'}]
const tab=ref('storage'),plan=ref<StoragePlan>(),volumes=ref<ApplicationVolume[]>([]),opened=ref(false),busy=ref(false),setupKey=ref(0),initialPurpose=ref<Purpose>('files'),feedback=ref(''),dialog=ref<HTMLElement>(),foreignOpen=ref(false),ordinaryOpen=ref(false),showDetails=ref(false)
const volumeOpen=ref(false),volumeKind=ref<'docker'|'management'>('docker'),volumeName=ref(''),volumeSize=ref(16)
const connectVolumeId=ref<number>(),connectAck=ref(false),connectStep=ref<'review'|'running'|'done'>('review'),connectProgress=ref(0)
const connectingVolume=computed(()=>volumes.value.find(item=>item.id===connectVolumeId.value))
const activeDockerVolume=computed(()=>volumes.value.find(item=>item.kind==='docker'&&item.connected))
const connectionSteps=['核对数据位置与目标容量','停止 Docker','迁移数据并核对结果','切换存储并启动 Docker']
let connectionTimer:ReturnType<typeof setInterval>|undefined
function openConnection(id:number){connectVolumeId.value=id;connectAck.value=false;connectProgress.value=0;connectStep.value=connectingVolume.value?.connected?'done':'review'}
function closeConnection(){if(connectStep.value!=='running')connectVolumeId.value=undefined}
function connectDocker(){if(!connectAck.value||!connectingVolume.value)return;connectStep.value='running';busy.value=true;connectionTimer=setInterval(()=>{connectProgress.value++;if(connectProgress.value===connectionSteps.length){clearInterval(connectionTimer);for(const item of volumes.value)if(item.kind==='docker')item.connected=item.id===connectVolumeId.value;connectStep.value='done';busy.value=false}},550)}
const hasExistingFiles=computed(()=>scene.value==='ordinary'&&target.value.kind!=='free')
const foreign=computed(()=>scene.value==='foreign')
const planSummary=computed(()=>plan.value?[plan.value.files?`普通文件存储 ${plan.value.files} GiB · EXT4`:'',plan.value.hosts?`主机存储 ${plan.value.hosts} GiB`:'',plan.value.apps?`应用存储 ${plan.value.apps} GiB`:'',plan.value.management==='separate'?`管理文件区 ${plan.value.managementSize} GiB`:''].filter(Boolean).join(' · '):'')
const volumeCapacity=computed(()=>volumes.value.reduce((sum,item)=>sum+item.capacity,0)),available=computed(()=>(plan.value?.apps||0)-volumeCapacity.value),used=computed(()=>volumes.value.reduce((sum,item)=>sum+item.used,0))
const validVolumeSize=computed(()=>Number.isInteger(volumeSize.value)&&volumeSize.value>=1&&volumeSize.value<=available.value)
let timer:ReturnType<typeof setTimeout>|undefined
function toast(message:string){feedback.value=message;if(timer)clearTimeout(timer);timer=setTimeout(()=>feedback.value='',5000)}
function close(){if(!busy.value)opened.value=false}
function backToOverview(){router.replace({query:{...route.query,variant:'A'}})}
function closeInfo(){foreignOpen.value=false;ordinaryOpen.value=false;showDetails.value=false}
function reset(){if(connectionTimer)clearInterval(connectionTimer);connectVolumeId.value=undefined;busy.value=false;plan.value=undefined;volumes.value=[];opened.value=false;tab.value='storage';volumeOpen.value=false;closeInfo();feedback.value='';initialPurpose.value='files';setupKey.value++;if(scene.value==='managed')complete({purpose:'both',hosts:Math.floor(target.value.capacity*.625/4)*4,apps:target.value.capacity-Math.floor(target.value.capacity*.625/4)*4,management:'application',managementSize:16});if(scene.value==='mixed')complete({purpose:'both',files:24,hosts:Math.floor((target.value.capacity-24)*.625/4)*4,apps:target.value.capacity-24-Math.floor((target.value.capacity-24)*.625/4)*4,management:'application',managementSize:16,fileMount:'/mnt/'+target.value.token.replace('-free','-data')})}
function changeScene(e:Event){router.replace({query:{...route.query,scene:(e.target as HTMLSelectElement).value}})}
function changeTarget(e:Event){router.replace({query:{...route.query,target:(e.target as HTMLSelectElement).value}})}
function openSetup(purpose:Purpose='files'){if(foreign.value){foreignOpen.value=true;return}if(plan.value){toast('这块空间已经在使用。请选择另一块未使用空间；当前演示不提供在线重新划分。');return}initialPurpose.value=purpose;opened.value=true;setupKey.value++}
function complete(value:StoragePlan){plan.value=value;if(value.management==='application'&&!volumes.value.some(item=>item.kind==='management'))volumes.value.push({id:Date.now(),kind:'management',name:'LightHost 管理文件',capacity:value.managementSize,used:.8})}
function openFiles(){toast('演示：打开 '+(plan.value?.fileMount||'/mnt/'+target.value.token)+' 中的文件。现有文件不被清空。')}
function showVolumes(){opened.value=false;tab.value='volumes';openVolume()}
function openVolume(){volumeName.value='';volumeKind.value='docker';volumeSize.value=Math.min(16,available.value);volumeOpen.value=true}
function createVolume(){if(!validVolumeSize.value||!plan.value?.apps)return;volumes.value.push({id:Date.now(),kind:volumeKind.value,name:volumeName.value.trim()||(volumeKind.value==='docker'?'Docker 数据':'LightHost 管理文件'),capacity:volumeSize.value,used:0});volumeOpen.value=false;toast('应用卷已创建（演示）。接下来由对应应用完成接入。')}
function keydown(e:KeyboardEvent){const modal=opened.value&&variant.value==='A'||volumeOpen.value||foreignOpen.value||ordinaryOpen.value||showDetails.value||connectingVolume.value;if(!modal)return;if(e.key==='Escape'){if(connectingVolume.value)closeConnection();else if(volumeOpen.value)volumeOpen.value=false;else if(foreignOpen.value||ordinaryOpen.value||showDetails.value)closeInfo();else close()}if(e.key!=='Tab'||!dialog.value)return;const controls=Array.from(dialog.value.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),summary,a[href]'));const first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===dialog.value)){e.preventDefault();last?.focus()}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===dialog.value)){e.preventDefault();first?.focus()}}
watch([scene,target],reset,{immediate:true})
watch(variant,()=>{if(connectionTimer)clearInterval(connectionTimer);connectVolumeId.value=undefined;opened.value=false;volumeOpen.value=false;busy.value=false;setupKey.value++;closeInfo()})
watch([opened,volumeOpen,foreignOpen,ordinaryOpen,showDetails,connectVolumeId],async()=>{await nextTick();dialog.value?.focus()})
onMounted(()=>document.addEventListener('keydown',keydown))
onUnmounted(()=>{if(connectionTimer)clearInterval(connectionTimer);if(timer)clearTimeout(timer);document.removeEventListener('keydown',keydown)})
</script>
<style src="./lighthostStoragePrototype.css"></style>
